import * as React from 'react';
import {
  CHANGELOG,
  DEFAULT_SETTINGS,
  DM_VERSION,
  SYSTEM_ICONS,
  SYSTEM_LABELS,
  THEMES,
  TOOLBAR_WIDGETS,
  WIDGET_LABELS,
} from './constants.js';
import {
  decodeShieldCode,
  deepClone,
  downloadShieldJson,
  encodeShieldCode,
  importShieldPayload,
  loadCurrentShieldId,
  loadShields,
  migrateShield,
  migrateWidget,
  saveCurrentShieldId,
  saveShields,
  uid,
} from './storage.js';
import { buildPJQuick, decodePJLiteSeed, readPJLiteSaves } from './pjLiteBridge.js';
import { presetShield, READY_PRESETS } from './presets.js';

const { useCallback, useEffect, useMemo, useRef, useState } = React;

function useMedia(query) {
  const [matches, setMatches] = useState(() => typeof window !== 'undefined' && window.matchMedia(query).matches);
  useEffect(() => {
    const media = window.matchMedia(query);
    const listener = () => setMatches(media.matches);
    listener();
    media.addEventListener?.('change', listener);
    return () => media.removeEventListener?.('change', listener);
  }, [query]);
  return matches;
}

function formatDate(iso) {
  try { return new Date(iso).toLocaleString('pt-BR', { dateStyle: 'short', timeStyle: 'short' }); }
  catch { return '—'; }
}
function systemLabel(system) { return SYSTEM_LABELS[system] || system || 'Genérico'; }
function systemIcon(system) { return SYSTEM_ICONS[system] || '🛡️'; }

function Modal({ open, title, onClose, size = 'md', children }) {
  if (!open) return null;
  return <div className="dm-modal-layer" onPointerDown={e => { if (e.target === e.currentTarget) onClose?.(); }}>
    <section className={`dm-modal dm-modal--${size}`}>
      <header className="dm-modal__head"><h2>{title}</h2><button onClick={onClose} aria-label="Fechar">×</button></header>
      <div className="dm-modal__body">{children}</div>
    </section>
  </div>;
}

function Toast({ toast, onUndo, onDismiss }) {
  if (!toast) return null;
  return <div className="dm-toast" role="status"><span>{toast.message}</span>{toast.undo && <button onClick={() => { onUndo?.(); onDismiss?.(); }}>Desfazer</button>}<button className="dm-toast__close" onClick={onDismiss} aria-label="Fechar">×</button></div>;
}
function EmptyState({ children }) { return <div className="dm-empty"><div className="dm-empty__icon">🛡️</div>{children}</div>; }
function Button({ className = '', children, ...props }) { return <button className={`dm-btn ${className}`} {...props}>{children}</button>; }

function Home({ shields, onOpen, onCreate, onImport, onEdit, onDuplicate, onDelete, onExport, onOpenUpdates, onOpenAbout }) {
  const [query, setQuery] = useState('');
  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    return [...shields].sort((a, b) => String(b.updatedAt || '').localeCompare(String(a.updatedAt || ''))).filter(s => !q || [s.name, s.genre, systemLabel(s.system)].some(v => String(v || '').toLowerCase().includes(q)));
  }, [shields, query]);
  return <div className="dm-home"><div className="dm-home__shell">
    <div className="dm-home__brandrow"><div><span className="dm-home__brand">◆ DM Lite</span><span className="dm-version">{DM_VERSION}</span></div><div className="dm-home__mini-actions"><Button onClick={onOpenUpdates}>✨ Atualizações</Button><Button onClick={onOpenAbout}>ⓘ Sobre</Button><a className="dm-btn" href="/" target="_blank" rel="noreferrer">PJ Lite ↗</a></div></div>
    <section className="dm-news"><div><strong>✨ DM Lite {DM_VERSION} — versão funcional</strong><p>Agora o DM Lite vive no mesmo projeto React/Vite do PJ Lite, com saves reais, integração local e mobile próprio.</p></div><span>React/Vite</span></section>
    <div className="dm-home__title-row"><div><h1>Meus Escudos</h1><p>Abra uma campanha, continue sua mesa ou crie um novo escudo pronto.</p></div><div className="dm-home__actions"><Button onClick={onImport}>⇩ Importar Escudo</Button><Button className="dm-btn--accent" onClick={onCreate}>＋ Novo Escudo</Button></div></div>
    <div className="dm-home__search"><input value={query} onChange={e => setQuery(e.target.value)} placeholder="🔎 Buscar por nome, gênero ou sistema..." /></div>
    {filtered.length === 0 ? <EmptyState><strong>{query ? 'Nenhum escudo encontrado.' : 'Você ainda não criou nenhum escudo.'}</strong><p>{query ? 'Tente outro termo.' : 'Clique em “Novo Escudo” para começar.'}</p></EmptyState> : <div className="dm-shield-grid">{filtered.map(shield => <article key={shield.id} className="dm-shield-card" data-system={shield.system}>
      <span className="dm-system-tag">{systemLabel(shield.system)}</span><div className="dm-shield-card__hero"><div className="dm-shield-card__icon">{systemIcon(shield.system)}</div><div className="dm-shield-card__identity"><h3>{shield.name}</h3><b>{shield.genre || 'Sem gênero definido'}</b><small>Atualizado {formatDate(shield.updatedAt)}</small></div></div>
      <div className="dm-shield-card__stats"><div><strong>{shield.widgets?.length || 0}</strong><span>Janelas</span></div><div><strong>{systemLabel(shield.system)}</strong><span>Base</span></div></div>
      <div className="dm-shield-card__actions"><Button className="dm-btn--accent" onClick={() => onOpen(shield.id)}>Abrir</Button><Button title="Duplicar" onClick={() => onDuplicate(shield.id)}>⧉</Button><Button title="Editar nome e gênero" onClick={() => onEdit(shield.id)}>✎</Button><Button title="Exportar / compartilhar" onClick={() => onExport(shield.id)}>⇧</Button><Button className="dm-btn--danger" title="Apagar" onClick={() => onDelete(shield.id)}>🗑</Button></div>
    </article>)}</div>}
  </div></div>;
}

function CreateShieldModal({ open, onClose, onCreate }) {
  const [kind, setKind] = useState('blank'); const [name, setName] = useState('Novo Escudo'); const [genre, setGenre] = useState('Genérico');
  useEffect(() => { if (open) { setKind('blank'); setName('Novo Escudo'); setGenre('Genérico'); } }, [open]);
  const choose = key => { setKind(key); const p = READY_PRESETS[key]; setName(key === 'blank' ? 'Novo Escudo' : `Escudo ${p.label}`); setGenre(p.genre); };
  return <Modal open={open} title="＋ Criar Escudo" onClose={onClose} size="lg"><div className="dm-form-grid"><label>Nome do escudo<input value={name} onChange={e => setName(e.target.value)} /></label><label>Gênero / Tema<input value={genre} onChange={e => setGenre(e.target.value)} /></label></div><h3 className="dm-section-title">Começar em branco ou pegar um pronto</h3><div className="dm-preset-grid">{Object.entries(READY_PRESETS).map(([key, p]) => <button key={key} className={`dm-preset-card ${kind === key ? 'is-selected' : ''}`} onClick={() => choose(key)}><span>{p.icon}</span><strong>{p.label}</strong><small>{p.description}</small></button>)}</div><div className="dm-modal__footer"><Button onClick={onClose}>Cancelar</Button><Button className="dm-btn--accent" onClick={() => onCreate(kind, name.trim() || 'Novo Escudo', genre.trim())}>Criar e Abrir</Button></div></Modal>;
}

function EditShieldModal({ shield, onClose, onSave }) {
  const [name, setName] = useState(''); const [genre, setGenre] = useState('');
  useEffect(() => { setName(shield?.name || ''); setGenre(shield?.genre || ''); }, [shield]);
  return <Modal open={!!shield} title="✎ Dados do Escudo" onClose={onClose}><div className="dm-form-stack"><label>Nome do escudo<input value={name} onChange={e => setName(e.target.value)} /></label><label>Gênero / Tema<input value={genre} onChange={e => setGenre(e.target.value)} placeholder="Fantasia, Terror, Sci-fi..." /></label></div><div className="dm-modal__footer"><Button onClick={onClose}>Cancelar</Button><Button className="dm-btn--accent" onClick={() => name.trim() && onSave(name.trim(), genre.trim())}>Salvar</Button></div></Modal>;
}

function ImportShieldModal({ open, onClose, onImportPayload, onImportCode }) {
  const [code, setCode] = useState(''); const fileRef = useRef(null); useEffect(() => { if (open) setCode(''); }, [open]);
  const onFile = e => { const file = e.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => { try { onImportPayload(JSON.parse(reader.result)); } catch { onImportPayload(null, 'Arquivo JSON inválido.'); } }; reader.readAsText(file); e.target.value = ''; };
  return <Modal open={open} title="⇩ Importar Escudo" onClose={onClose} size="lg"><div className="dm-two-panels"><section className="dm-panel"><h3>Arquivo JSON</h3><p>Melhor opção para backup completo do escudo.</p><Button className="dm-btn--accent" onClick={() => fileRef.current?.click()}>Escolher arquivo</Button><input ref={fileRef} hidden type="file" accept=".json,application/json" onChange={onFile} /></section><section className="dm-panel"><h3>Código compartilhável</h3><p>Aceita códigos novos <b>DMLITE2:</b> e os antigos <b>DMLITE1:</b>.</p><textarea rows="7" value={code} onChange={e => setCode(e.target.value)} placeholder="DMLITE2:..." /><Button className="dm-btn--accent" onClick={() => onImportCode(code)}>Importar código</Button></section></div></Modal>;
}

function ExportShieldModal({ shield, onClose, notify }) {
  const code = useMemo(() => shield ? encodeShieldCode(shield) : '', [shield]);
  const copy = async () => { try { await navigator.clipboard.writeText(code); notify('Código do escudo copiado.'); } catch { const ta = document.createElement('textarea'); ta.value = code; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); ta.remove(); notify('Código do escudo copiado.'); } };
  return <Modal open={!!shield} title="⇧ Exportar / Compartilhar" onClose={onClose} size="lg">{shield && <><section className="dm-panel"><h3>{shield.name}</h3><p>Arquivo JSON para backup; código para compartilhar rapidamente.</p><div className="dm-inline"><Button className="dm-btn--accent" onClick={() => { downloadShieldJson(shield); notify('Arquivo do escudo exportado.'); }}>⇩ Baixar JSON</Button><Button onClick={copy}>⧉ Copiar Código</Button></div></section><label className="dm-label">Código do escudo<textarea rows="8" readOnly value={code} /></label></>}</Modal>;
}

function PJImportModal({ open, onClose, onImport, notify }) {
  const [items, setItems] = useState([]); const [query, setQuery] = useState(''); const [seed, setSeed] = useState('');
  useEffect(() => { if (open) { setItems(readPJLiteSaves()); setQuery(''); setSeed(''); } }, [open]);
  const filtered = items.filter(({ quick }) => !query || `${quick.name} ${quick.subtitle} ${systemLabel(quick.system)}`.toLowerCase().includes(query.toLowerCase()));
  const importSeed = () => { try { onImport(decodePJLiteSeed(seed)); } catch (e) { notify(e.message || 'Código inválido.'); } };
  return <Modal open={open} title="👤 Importar do PJ Lite" onClose={onClose} size="xl"><div className="dm-pj-import-tabs"><section className="dm-panel"><h3>Salvos neste navegador</h3><p>Como PJ Lite e DM Lite estão no mesmo domínio, estas fichas podem ser lidas diretamente.</p><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Buscar ficha..." /><div className="dm-pj-save-list">{filtered.length ? filtered.map(({ item, quick }) => <button key={`${item.id}-${quick.name}`} onClick={() => onImport({ item, quick })}><strong>{quick.name}</strong><span>{quick.subtitle}</span><small>{systemLabel(quick.system)}</small></button>) : <div className="dm-muted">Nenhuma ficha encontrada neste navegador.</div>}</div></section><section className="dm-panel"><h3>Código da Ficha</h3><p>Fallback para trazer uma ficha de outro navegador/dispositivo.</p><textarea rows="9" value={seed} onChange={e => setSeed(e.target.value)} placeholder="Cole o Código da Ficha do PJ Lite..."/><Button className="dm-btn--accent" onClick={importSeed}>Importar código</Button></section></div></Modal>;
}

function SettingsModal({ open, settings, onClose, onChange }) { return <Modal open={open} title="⚙ Configurações" onClose={onClose}><div className="dm-form-stack"><label>Tema<select value={settings.theme} onChange={e => onChange({ theme: e.target.value })}>{Object.entries(THEMES).map(([k, t]) => <option key={k} value={k}>{t.label}</option>)}</select></label><label>Tamanho global da interface <div className="dm-inline"><Button onClick={() => onChange({ fontSize: Math.max(12, settings.fontSize - 1) })}>A−</Button><b>{settings.fontSize}px</b><Button onClick={() => onChange({ fontSize: Math.min(22, settings.fontSize + 1) })}>A+</Button></div></label><label>Plano de fundo<select value={settings.backgroundType} onChange={e => onChange({ backgroundType: e.target.value })}><option value="theme">Cor do tema</option><option value="color">Cor personalizada</option><option value="image">Imagem por URL</option></select></label>{settings.backgroundType === 'color' && <label>Cor<input type="color" value={settings.backgroundValue || '#11100f'} onChange={e => onChange({ backgroundValue: e.target.value })} /></label>}{settings.backgroundType === 'image' && <label>URL da imagem<input value={settings.backgroundValue || ''} onChange={e => onChange({ backgroundValue: e.target.value })} placeholder="https://..." /></label>}</div></Modal>; }
function SearchModal({ open, widgets, onClose, onSelect }) { const [q, setQ] = useState(''); useEffect(() => { if (open) setQ(''); }, [open]); const rows = widgets.filter(w => !q || JSON.stringify(w).toLowerCase().includes(q.toLowerCase())).slice(0, 30); return <Modal open={open} title="⌕ Pesquisar na Mesa" onClose={onClose}><input autoFocus value={q} onChange={e => setQ(e.target.value)} placeholder="Nome, nota, NPC..."/><div className="dm-search-results">{rows.map(w => <button key={w.id} onClick={() => onSelect(w.id)}><strong>{w.title}</strong><small>{WIDGET_LABELS[w.type] || w.type}</small></button>)}</div></Modal>; }
function UpdatesModal({ open, onClose }) { return <Modal open={open} title="✨ Log de Atualizações" onClose={onClose} size="lg"><div className="dm-changelog">{CHANGELOG.map(row => <article key={row.version}><strong>{row.version} — {row.title}</strong><p>{row.text}</p></article>)}</div></Modal>; }
function AboutModal({ open, onClose }) { return <Modal open={open} title="ⓘ Sobre o DM Lite" onClose={onClose} size="lg"><section className="dm-panel"><h3>Projeto de Código Aberto 🔓</h3><p>Ferramenta gratuita, sem coleta de dados e sem fins lucrativos. Os escudos ficam armazenados localmente no navegador, como no PJ Lite.</p><p>O código está no mesmo repositório do PJ Lite para facilitar manutenção e atualização.</p></section><section className="dm-panel"><h3>Comunidade</h3><a className="dm-telegram" href="https://t.me/boost/Baianoviado" target="_blank" rel="noreferrer">✈ Canal de anúncios e novidades no Telegram ↗</a><p><b>Desenvolvido por Nick Queijo</b></p></section></Modal>; }

function nextWidgetPosition(widgets, workspace, width = 360, height = 310) { const rect = workspace?.getBoundingClientRect?.(); const maxW = rect?.width || 1200; const gap = 14; const cols = Math.max(1, Math.floor((maxW - gap) / (width + gap))); for (let i = 0; i < Math.max(16, widgets.length + 6); i++) { const x = gap + (i % cols) * (width + gap); const y = gap + Math.floor(i / cols) * (height + gap); const collision = widgets.some(w => !w.minimized && Math.abs((w.x || 0) - x) < 60 && Math.abs((w.y || 0) - y) < 60); if (!collision) return { x, y }; } return { x: 20 + (widgets.length % 5) * 24, y: 20 + (widgets.length % 5) * 24 }; }
function createWidget(type, widgets, workspace) { const dims = type === 'initiative' ? { w: 490, h: 340 } : type === 'reference' ? { w: 430, h: 330 } : { w: 360, h: 310 }; const pos = nextWidgetPosition(widgets, workspace, dims.w, dims.h); return migrateWidget({ id: uid('widget'), type, title: WIDGET_LABELS[type] || 'Janela', ...pos, ...dims, z: Math.max(10, ...widgets.map(w => Number(w.z) || 1)) + 1 }); }

function ShieldEditor({ shield, onChange, onBack, notify, pushUndo }) {
  const isMobile = useMedia('(max-width: 760px)'); const workspaceRef = useRef(null); const [pjOpen, setPjOpen] = useState(false); const [settingsOpen, setSettingsOpen] = useState(false); const [searchOpen, setSearchOpen] = useState(false); const [mobileFocusId, setMobileFocusId] = useState(null);
  const widgets = shield.widgets || []; const settings = { ...DEFAULT_SETTINGS, ...(shield.settings || {}) }; const theme = THEMES[settings.theme] || THEMES.amber;
  useEffect(() => { document.title = `${shield.name} — DM Lite`; return () => { document.title = 'PJ Lite'; }; }, [shield.name]); useEffect(() => { if (!isMobile) setMobileFocusId(null); }, [isMobile]);
  const patchShield = useCallback(patch => onChange(prev => ({ ...prev, ...(typeof patch === 'function' ? patch(prev) : patch), updatedAt: new Date().toISOString() })), [onChange]);
  const setWidgets = useCallback(next => onChange(prev => ({ ...prev, widgets: typeof next === 'function' ? next(prev.widgets || []) : next, updatedAt: new Date().toISOString() })), [onChange]);
  const patchWidget = useCallback((id, patch) => setWidgets(list => list.map(w => w.id === id ? { ...w, ...(typeof patch === 'function' ? patch(w) : patch) } : w)), [setWidgets]);
  const addWidget = type => { const w = createWidget(type, widgets, workspaceRef.current); setWidgets([...widgets, w]); if (isMobile) setMobileFocusId(w.id); };
  const deleteWidget = id => { const index = widgets.findIndex(w => w.id === id); if (index < 0) return; const gone = deepClone(widgets[index]); setWidgets(widgets.filter(w => w.id !== id)); if (mobileFocusId === id) setMobileFocusId(null); pushUndo('Janela movida para a lixeira.', () => setWidgets(current => { const next = [...current]; next.splice(Math.min(index, next.length), 0, gone); return next; })); };
  const duplicateWidget = id => { const source = widgets.find(w => w.id === id); if (!source) return; const copy = migrateWidget({ ...deepClone(source), id: uid('widget'), title: `${source.title} (Cópia)`, x: (source.x || 0) + 28, y: (source.y || 0) + 28, z: Math.max(10, ...widgets.map(w => Number(w.z) || 1)) + 1, minimized: false }); setWidgets([...widgets, copy]); };
  const bringToFront = id => { if (isMobile) return; const nextZ = Math.max(10, ...widgets.map(w => Number(w.z) || 1)) + 1; patchWidget(id, { z: nextZ }); };
  const reorderMobile = (id, dir) => { const index = widgets.findIndex(w => w.id === id); const target = index + dir; if (index < 0 || target < 0 || target >= widgets.length) return; const next = [...widgets]; [next[index], next[target]] = [next[target], next[index]]; setWidgets(next); };
  const arrange = () => { if (isMobile) return notify('No celular as janelas já são organizadas automaticamente em pilha.'); const rect = workspaceRef.current?.getBoundingClientRect(); if (!rect) return; const gap = 12; const cols = rect.width >= 1180 ? 3 : rect.width >= 760 ? 2 : 1; const cellW = Math.max(300, Math.floor((rect.width - gap * (cols + 1)) / cols)); const cellH = 320; setWidgets(widgets.map((w, i) => ({ ...w, x: gap + (i % cols) * (cellW + gap), y: gap + Math.floor(i / cols) * (cellH + gap), w: cellW, h: w.type === 'reference' ? 340 : cellH, z: i + 1 }))); };
  const addPJ = ({ item, quick }) => { const w = createWidget('pj', widgets, workspaceRef.current); Object.assign(w, { title: `PJ — ${quick.name}`, pjData: item, quick, w: 420, h: 360 }); setWidgets([...widgets, w]); setPjOpen(false); if (isMobile) setMobileFocusId(w.id); notify(`“${quick.name}” adicionado ao escudo.`); };
  const addCombatant = data => { let initiative = widgets.find(w => w.type === 'initiative'); if (!initiative) { initiative = createWidget('initiative', widgets, workspaceRef.current); initiative.combatants = []; initiative.round = 1; initiative.activeId = null; const combatant = { id: uid('c'), ...data }; initiative.combatants.push(combatant); initiative.activeId = combatant.id; setWidgets([...widgets, initiative]); } else { const combatant = { id: uid('c'), ...data }; patchWidget(initiative.id, { combatants: [...(initiative.combatants || []), combatant], activeId: initiative.activeId || combatant.id }); } notify('Adicionado à iniciativa.'); };
  const backgroundStyle = settings.backgroundType === 'image' && settings.backgroundValue ? { backgroundImage: `linear-gradient(rgba(0,0,0,${1 - settings.backgroundOpacity}),rgba(0,0,0,${1 - settings.backgroundOpacity})),url(${settings.backgroundValue})` } : settings.backgroundType === 'color' && settings.backgroundValue ? { background: settings.backgroundValue } : {};
  const rootStyle = { '--dm-accent': theme.accent, '--dm-bg': theme.bg, '--dm-panel': theme.panel, '--dm-font-size': `${settings.fontSize}px` }; const visibleWidgets = isMobile && mobileFocusId ? widgets.filter(w => w.id === mobileFocusId) : widgets;
  return <div className="dm-app" style={rootStyle}><header className="dm-topbar"><div className="dm-topbar__brand"><Button onClick={onBack}>← Home</Button><div><strong>◆ DM Lite</strong><small>{shield.name}</small></div></div><div className="dm-topbar__tools">{TOOLBAR_WIDGETS.map(([type, icon, label]) => <Button key={type} onClick={() => addWidget(type)} title={`Adicionar ${label}`}>{icon}<span>{label}</span></Button>)}</div><div className="dm-topbar__right"><Button onClick={() => setPjOpen(true)}>👤<span>PJ Lite</span></Button><Button onClick={arrange} title="Organizar">▦</Button><Button onClick={() => setSearchOpen(true)} title="Pesquisar">⌕</Button><Button onClick={() => setSettingsOpen(true)} title="Configurações">⚙</Button></div></header>
    <main ref={workspaceRef} className={`dm-workspace ${isMobile ? 'dm-workspace--mobile' : ''} ${mobileFocusId ? 'dm-workspace--focus' : ''}`} style={backgroundStyle}>{!widgets.length && <EmptyState><strong>Seu escudo está vazio.</strong><p>Adicione uma Nota, Iniciativa, Dados ou importe uma ficha do PJ Lite.</p></EmptyState>}{visibleWidgets.map(widget => <WidgetShell key={widget.id} widget={widget} isMobile={isMobile} focused={mobileFocusId === widget.id} workspaceRef={workspaceRef} onPatch={patch => patchWidget(widget.id, patch)} onDelete={() => deleteWidget(widget.id)} onDuplicate={() => duplicateWidget(widget.id)} onBring={() => bringToFront(widget.id)} onMoveUp={() => reorderMobile(widget.id, -1)} onMoveDown={() => reorderMobile(widget.id, 1)} onFocus={() => setMobileFocusId(widget.id)} onUnfocus={() => setMobileFocusId(null)}><WidgetContent widget={widget} onPatch={patch => patchWidget(widget.id, patch)} notify={notify} pushUndo={pushUndo} addCombatant={addCombatant} /></WidgetShell>)}</main>
    <footer className="dm-taskbar"><span>Janelas ({widgets.length})</span>{widgets.map(w => <button key={w.id} className={mobileFocusId === w.id ? 'is-active' : ''} onClick={() => { if (isMobile) setMobileFocusId(mobileFocusId === w.id ? null : w.id); else { patchWidget(w.id, { minimized: false }); bringToFront(w.id); } }}>{w.minimized ? '— ' : ''}{w.title}</button>)}</footer>
    <PJImportModal open={pjOpen} onClose={() => setPjOpen(false)} onImport={addPJ} notify={notify} /><SettingsModal open={settingsOpen} settings={settings} onClose={() => setSettingsOpen(false)} onChange={patch => patchShield({ settings: { ...settings, ...patch } })} /><SearchModal open={searchOpen} widgets={widgets} onClose={() => setSearchOpen(false)} onSelect={id => { const w = widgets.find(x => x.id === id); if (!w) return; patchWidget(id, { minimized: false }); if (isMobile) setMobileFocusId(id); else bringToFront(id); setSearchOpen(false); }} />
  </div>;
}

function WidgetShell({ widget, isMobile, focused, workspaceRef, onPatch, onDelete, onDuplicate, onBring, onMoveUp, onMoveDown, onFocus, onUnfocus, children }) {
  const elRef = useRef(null); const style = isMobile ? undefined : { left: widget.x, top: widget.y, width: widget.w, height: widget.minimized ? 44 : widget.h, zIndex: widget.z };
  const beginDrag = e => { if (isMobile || widget.locked || widget.minimized || ['INPUT', 'BUTTON', 'TEXTAREA', 'SELECT'].includes(e.target.tagName)) return; const el = elRef.current; const workspace = workspaceRef.current; if (!el || !workspace) return; e.preventDefault(); onBring(); const startX = e.clientX, startY = e.clientY, startLeft = widget.x, startTop = widget.y, pid = e.pointerId, rect = workspace.getBoundingClientRect(); try { e.currentTarget.setPointerCapture(pid); } catch {} const move = ev => { if (ev.pointerId !== pid) return; const x = Math.max(0, Math.min(startLeft + ev.clientX - startX, Math.max(0, rect.width - Math.min(widget.w, rect.width)))); const y = Math.max(0, Math.min(startTop + ev.clientY - startY, Math.max(0, rect.height - 48))); el.style.left = `${x}px`; el.style.top = `${y}px`; el.dataset.dragX = x; el.dataset.dragY = y; }; const end = ev => { if (ev.pointerId !== pid) return; e.currentTarget.removeEventListener('pointermove', move); e.currentTarget.removeEventListener('pointerup', end); e.currentTarget.removeEventListener('pointercancel', end); const x = Number(el.dataset.dragX ?? widget.x), y = Number(el.dataset.dragY ?? widget.y); delete el.dataset.dragX; delete el.dataset.dragY; onPatch({ x, y }); }; e.currentTarget.addEventListener('pointermove', move); e.currentTarget.addEventListener('pointerup', end); e.currentTarget.addEventListener('pointercancel', end); };
  const beginResize = e => { if (isMobile || widget.locked || widget.minimized) return; const el = elRef.current; const workspace = workspaceRef.current; if (!el || !workspace) return; e.preventDefault(); e.stopPropagation(); const sx = e.clientX, sy = e.clientY, sw = widget.w, sh = widget.h, pid = e.pointerId, rect = workspace.getBoundingClientRect(); try { e.currentTarget.setPointerCapture(pid); } catch {} const move = ev => { if (ev.pointerId !== pid) return; const width = Math.max(260, Math.min(sw + ev.clientX - sx, rect.width - widget.x)); const height = Math.max(200, Math.min(sh + ev.clientY - sy, rect.height - widget.y)); el.style.width = `${width}px`; el.style.height = `${height}px`; el.dataset.resizeW = width; el.dataset.resizeH = height; }; const end = ev => { if (ev.pointerId !== pid) return; e.currentTarget.removeEventListener('pointermove', move); e.currentTarget.removeEventListener('pointerup', end); e.currentTarget.removeEventListener('pointercancel', end); onPatch({ w: Number(el.dataset.resizeW ?? widget.w), h: Number(el.dataset.resizeH ?? widget.h) }); delete el.dataset.resizeW; delete el.dataset.resizeH; }; e.currentTarget.addEventListener('pointermove', move); e.currentTarget.addEventListener('pointerup', end); e.currentTarget.addEventListener('pointercancel', end); };
  return <section ref={elRef} className={`dm-widget ${widget.minimized ? 'is-minimized' : ''} ${focused ? 'is-focused' : ''}`} style={style} onPointerDown={onBring}><header className="dm-widget__head" onPointerDown={beginDrag}><span className="dm-widget__grip">{isMobile ? '≡' : widget.locked ? '•' : '⠿'}</span><input value={widget.title} onChange={e => onPatch({ title: e.target.value })} onPointerDown={e => e.stopPropagation()} /><div className="dm-widget__actions">{isMobile && !focused && <><button title="Mover para cima" onClick={e => { e.stopPropagation(); onMoveUp(); }}>↑</button><button title="Mover para baixo" onClick={e => { e.stopPropagation(); onMoveDown(); }}>↓</button></>}{isMobile && <button title={focused ? 'Voltar à pilha' : 'Focar janela'} onClick={e => { e.stopPropagation(); focused ? onUnfocus() : onFocus(); }}>{focused ? '❐' : '□'}</button>}<button title={widget.minimized ? 'Restaurar' : 'Minimizar'} onClick={e => { e.stopPropagation(); onPatch({ minimized: !widget.minimized }); }}>{widget.minimized ? '□' : '—'}</button><button title="Duplicar" onClick={e => { e.stopPropagation(); onDuplicate(); }}>⧉</button>{!isMobile && <button title={widget.locked ? 'Destrancar' : 'Trancar'} onClick={e => { e.stopPropagation(); onPatch({ locked: !widget.locked }); }}>{widget.locked ? '🔒' : '🔓'}</button>}<button className="danger" title="Apagar" onClick={e => { e.stopPropagation(); onDelete(); }}>🗑</button></div></header>{!widget.minimized && <div className="dm-widget__body">{children}</div>}{!isMobile && !widget.minimized && !widget.locked && <div className="dm-widget__resize" onPointerDown={beginResize}>↘</div>}</section>;
}

function WidgetContent({ widget, onPatch, notify, pushUndo, addCombatant }) { switch (widget.type) { case 'note': return <NoteWidget widget={widget} onPatch={onPatch} notify={notify} pushUndo={pushUndo} />; case 'dice': return <DiceWidget widget={widget} onPatch={onPatch} notify={notify} />; case 'initiative': return <InitiativeWidget widget={widget} onPatch={onPatch} notify={notify} pushUndo={pushUndo} />; case 'links': return <LinksWidget widget={widget} onPatch={onPatch} pushUndo={pushUndo} />; case 'image': return <ImageWidget widget={widget} onPatch={onPatch} notify={notify} />; case 'table': return <TableWidget widget={widget} onPatch={onPatch} notify={notify} pushUndo={pushUndo} />; case 'npc': return <NpcWidget widget={widget} onPatch={onPatch} addCombatant={addCombatant} />; case 'clock': return <ClockWidget widget={widget} onPatch={onPatch} />; case 'reference': return <ReferenceWidget widget={widget} />; case 'pj': return <PJWidget widget={widget} addCombatant={addCombatant} />; default: return <div className="dm-muted">Widget desconhecido.</div>; } }

function NoteWidget({ widget, onPatch, notify, pushUndo }) {
  const pages = widget.pages?.length ? widget.pages : [{ id: uid('page'), title: 'Nova Página', content: '' }]; const activeId = widget.activePageId || pages[0].id; const active = pages.find(p => p.id === activeId) || pages[0]; const editorRef = useRef(null); const savedRangeRef = useRef(null); const [sizeMenu, setSizeMenu] = useState(false);
  useEffect(() => { if (editorRef.current && editorRef.current.innerHTML !== (active.content || '')) editorRef.current.innerHTML = active.content || ''; }, [active.id]);
  const captureSelection = () => { const sel = window.getSelection(); if (!sel || !sel.rangeCount) return null; const range = sel.getRangeAt(0); if (range.collapsed) return null; const node = range.commonAncestorContainer.nodeType === 3 ? range.commonAncestorContainer.parentNode : range.commonAncestorContainer; if (!editorRef.current?.contains(node)) return null; savedRangeRef.current = range.cloneRange(); return savedRangeRef.current; };
  const restore = () => { const r = savedRangeRef.current; if (!r) return false; const sel = window.getSelection(); sel.removeAllRanges(); sel.addRange(r.cloneRange()); return true; };
  const commit = () => { const html = editorRef.current?.innerHTML || ''; onPatch({ pages: pages.map(p => p.id === active.id ? { ...p, content: html } : p) }); };
  const apply = (cmd, val) => { captureSelection(); if (!restore()) return notify('Selecione primeiro o trecho que deseja formatar.'); editorRef.current?.focus(); restore(); try { document.execCommand('styleWithCSS', false, true); } catch {} document.execCommand(cmd, false, val); commit(); captureSelection(); };
  const fontSize = px => { captureSelection(); if (!restore()) return notify('Selecione primeiro o trecho que deseja formatar.'); editorRef.current?.focus(); restore(); document.execCommand('fontSize', false, '7'); editorRef.current?.querySelectorAll('font[size="7"]').forEach(font => { const span = document.createElement('span'); span.style.fontSize = `${px}px`; while (font.firstChild) span.appendChild(font.firstChild); font.replaceWith(span); }); commit(); setSizeMenu(false); captureSelection(); };
  const removePage = id => { if (pages.length <= 1) return notify('A Nota precisa ter pelo menos uma página.'); const idx = pages.findIndex(p => p.id === id); const gone = deepClone(pages[idx]); const next = pages.filter(p => p.id !== id); const newActive = activeId === id ? next[0].id : activeId; onPatch({ pages: next, activePageId: newActive }); pushUndo('Página apagada.', () => { const restored = [...next]; restored.splice(Math.min(idx, restored.length), 0, gone); onPatch({ pages: restored, activePageId: gone.id }); }); };
  return <div className="dm-note"><div className="dm-note__toggle"><Button onClick={() => onPatch({ noteToolsHidden: !widget.noteToolsHidden })}>{widget.noteToolsHidden ? '▾ Mostrar ferramentas' : '▴ Ocultar ferramentas'}</Button><span>Selecione um trecho para formatar somente aquela parte.</span></div>{!widget.noteToolsHidden && <div className="dm-note__toolbar" onPointerDown={captureSelection}><button onMouseDown={e => e.preventDefault()} onClick={() => apply('bold')}><b>B</b></button><button onMouseDown={e => e.preventDefault()} onClick={() => apply('italic')}><i>I</i></button><button onMouseDown={e => e.preventDefault()} onClick={() => apply('underline')}><u>U</u></button><div className="dm-font-picker"><button onMouseDown={e => e.preventDefault()} onClick={() => setSizeMenu(v => !v)}>Tamanho ▾</button>{sizeMenu && <div>{[11,12,14,16,18,20,24,28,32].map(n => <button key={n} onMouseDown={e => e.preventDefault()} onClick={() => fontSize(n)}>{n}px</button>)}</div>}</div><input type="color" defaultValue="#e7e5e4" title="Cor do texto" onPointerDown={captureSelection} onInput={e => apply('foreColor', e.currentTarget.value)} /><button onMouseDown={e => e.preventDefault()} onClick={() => apply('removeFormat')}>Tx</button><button onClick={() => { const q = prompt('Pesquisar nesta página:'); if (q) notify(editorRef.current?.innerText.toLowerCase().includes(q.toLowerCase()) ? 'Texto encontrado nesta página.' : 'Não encontrado.'); }}>⌕</button></div>}<div className="dm-note__tabs">{pages.map(page => <div key={page.id} className={page.id === active.id ? 'is-active' : ''}><input value={page.title} onChange={e => onPatch({ pages: pages.map(p => p.id === page.id ? { ...p, title: e.target.value } : p) })} onClick={() => onPatch({ activePageId: page.id })}/>{pages.length > 1 && <button onClick={() => removePage(page.id)}>×</button>}</div>)}<button onClick={() => { const page = { id: uid('page'), title: `Pág ${pages.length + 1}`, content: '' }; onPatch({ pages: [...pages, page], activePageId: page.id }); }}>＋</button></div><div className="dm-note__stage"><div ref={editorRef} className="dm-note__paper" contentEditable suppressContentEditableWarning onInput={commit} onMouseUp={captureSelection} onKeyUp={captureSelection} onTouchEnd={() => setTimeout(captureSelection, 0)} /></div></div>;
}

function parseFormula(raw) { const m = String(raw || '').trim().match(/^(\d*)d(\d+)\s*([+-]\s*\d+)?$/i); if (!m) return null; return { qty: Math.max(1, Number(m[1] || 1)), sides: Math.max(2, Number(m[2])), mod: Number((m[3] || '0').replace(/\s/g, '')) }; }
function DiceWidget({ widget, onPatch, notify }) { const roll = (sides, qty = widget.qty, mod = widget.mod) => { const q = Math.max(1, Number(qty) || 1), m = Number(mod) || 0, values = Array.from({ length: q }, () => 1 + Math.floor(Math.random() * sides)), total = values.reduce((a, b) => a + b, 0) + m; onPatch({ result: total, qty: q, mod: m, history: [`${q}d${sides}${m ? (m > 0 ? '+' : '') + m : ''} → ${total} [${values.join(', ')}]`, ...(widget.history || [])].slice(0, 12) }); }; return <div className="dm-dice"><div className="dm-dice__result">{widget.result ?? '—'}</div><div className="dm-inline"><input value={widget.formula || ''} onChange={e => onPatch({ formula: e.target.value })} placeholder="2d6+3"/><Button onClick={() => { const f = parseFormula(widget.formula); if (!f) return notify('Use algo como 2d6+3.'); roll(f.sides, f.qty, f.mod); }}>Rolar</Button></div><div className="dm-dice__controls"><label>QTD<input type="number" value={widget.qty || 1} onChange={e => onPatch({ qty: e.target.value })}/></label><label>MOD<input type="number" value={widget.mod || 0} onChange={e => onPatch({ mod: e.target.value })}/></label></div><div className="dm-dice__buttons">{[4,6,8,10,12,20,100].map(d => <Button key={d} onClick={() => roll(d)}>D{d}</Button>)}</div><div className="dm-history">{(widget.history || []).map((h, i) => <div key={i}>{h}</div>)}</div></div>; }

function InitiativeWidget({ widget, onPatch, pushUndo }) { const list = widget.combatants || []; const activeId = widget.activeId && list.some(c => c.id === widget.activeId) ? widget.activeId : list[0]?.id || null; const round = widget.round || 1; const patchCombatant = (id, patch) => onPatch({ combatants: list.map(c => c.id === id ? { ...c, ...patch } : c) }); const remove = id => { const idx = list.findIndex(c => c.id === id), gone = deepClone(list[idx]); const next = list.filter(c => c.id !== id); onPatch({ combatants: next, activeId: activeId === id ? next[0]?.id || null : activeId }); pushUndo('Combatente removido.', () => { const restored = [...next]; restored.splice(Math.min(idx, restored.length), 0, gone); onPatch({ combatants: restored, activeId: gone.id }); }); }; const add = () => { const c = { id: uid('c'), name: 'Personagem', init: '', hp: '', cond: '' }; onPatch({ combatants: [...list, c], activeId: activeId || c.id }); }; const addGroup = () => { const name = prompt('Nome do grupo:', 'Goblin'); if (!name) return; const count = Math.max(1, Math.min(20, Number(prompt('Quantidade:', '3')) || 1)); const group = Array.from({ length: count }, (_, i) => ({ id: uid('c'), name: `${name} ${i + 1}`, init: '', hp: '', cond: '' })); onPatch({ combatants: [...list, ...group], activeId: activeId || group[0].id }); }; const moveTurn = dir => { if (!list.length) return; let idx = Math.max(0, list.findIndex(c => c.id === activeId)); let r = round; idx += dir; if (idx >= list.length) { idx = 0; r++; } if (idx < 0) { idx = list.length - 1; r = Math.max(1, r - 1); } onPatch({ activeId: list[idx].id, round: r }); }; return <div className="dm-init"><div className="dm-inline dm-wrap"><Button onClick={add}>＋ Combatente</Button><Button onClick={addGroup}>＋ Grupo</Button><Button onClick={() => onPatch({ combatants: [...list].sort((a, b) => (Number(b.init) || 0) - (Number(a.init) || 0)) })}>↕ Ordenar</Button><b>Rodada {round}</b></div><div className="dm-init__list">{list.map(c => <div key={c.id} className={c.id === activeId ? 'is-current' : ''}><span>{c.id === activeId ? '›' : ''}</span><input value={c.name} onChange={e => patchCombatant(c.id, { name: e.target.value })}/><input className="small" type="number" value={c.init} onChange={e => patchCombatant(c.id, { init: e.target.value })} placeholder="Init"/><input className="medium" value={c.hp} onChange={e => patchCombatant(c.id, { hp: e.target.value })} placeholder="PV"/><input value={c.cond} onChange={e => patchCombatant(c.id, { cond: e.target.value })} placeholder="Condição"/><button onClick={() => remove(c.id)}>×</button></div>)}</div>{list.length > 0 && <div className="dm-init__turn"><Button onClick={() => moveTurn(-1)}>‹</Button><strong>Turno: {list.find(c => c.id === activeId)?.name || '—'}</strong><Button onClick={() => moveTurn(1)}>Próximo ›</Button></div>}</div>; }

function LinksWidget({ widget, onPatch, pushUndo }) { const [title, setTitle] = useState(''); const [url, setUrl] = useState(''); const links = widget.links || []; const add = () => { if (!url.trim()) return; const final = /^https?:/i.test(url.trim()) ? url.trim() : `https://${url.trim()}`; onPatch({ links: [...links, { id: uid('link'), title: title.trim() || 'Novo Link', url: final }] }); setTitle(''); setUrl(''); }; const remove = (link, index) => { const next = links.filter(x => x.id !== link.id); onPatch({ links: next }); pushUndo('Link removido.', () => { const restored = [...next]; restored.splice(Math.min(index, restored.length), 0, link); onPatch({ links: restored }); }); }; return <div className="dm-links"><div className="dm-form-stack"><input value={title} onChange={e => setTitle(e.target.value)} placeholder="Nome do link"/><div className="dm-inline"><input value={url} onChange={e => setUrl(e.target.value)} onKeyDown={e => e.key === 'Enter' && add()} placeholder="URL..."/><Button onClick={add}>＋</Button></div></div><div>{links.map((l, i) => <div className="dm-link-row" key={l.id}><div><a href={l.url} target="_blank" rel="noreferrer">↗ {l.title}</a><small>{l.url}</small></div><button onClick={() => remove(l, i)}>×</button></div>)}</div></div>; }
function ImageWidget({ widget, onPatch, notify }) { const fileRef = useRef(null); const [url, setUrl] = useState(widget.imageUrlInput || ''); const upload = file => { if (!file) return; if (file.size > 2_500_000) notify('Imagem grande: pode ocupar bastante espaço no armazenamento local.'); const reader = new FileReader(); reader.onload = () => onPatch({ imageData: reader.result, imageUrlInput: '' }); reader.readAsDataURL(file); }; return <div className="dm-image-widget"><div className="dm-inline dm-wrap"><input value={url} onChange={e => setUrl(e.target.value)} placeholder="URL da imagem..."/><Button onClick={() => onPatch({ imageData: url, imageUrlInput: url })}>Carregar</Button><Button onClick={() => fileRef.current?.click()}>Upload</Button><input hidden ref={fileRef} type="file" accept="image/*" onChange={e => upload(e.target.files?.[0])}/><Button onClick={() => onPatch({ zoom: Math.max(40, (widget.zoom || 100) - 10) })}>−</Button><b>{widget.zoom || 100}%</b><Button onClick={() => onPatch({ zoom: Math.min(300, (widget.zoom || 100) + 10) })}>＋</Button></div><div className="dm-image-stage">{widget.imageData ? <img src={widget.imageData} alt="Referência" style={{ width: `${widget.zoom || 100}%` }}/> : <div className="dm-muted">Nenhuma imagem carregada.</div>}</div></div>; }

function TableWidget({ widget, onPatch, notify, pushUndo }) { const rows = widget.rows?.length ? widget.rows : [['',''],['','']]; const styles = widget.cellStyles || {}; const selected = widget.selectedCell; const key = selected ? `${selected.ri}:${selected.ci}` : ''; const currentStyle = key ? { fontSize:10,color:'#e7e5e4',bold:false,italic:false,underline:false,...(styles[key]||{}) } : { fontSize:10,color:'#e7e5e4',bold:false,italic:false,underline:false }; const patchStyle = patch => { if (!selected) return notify('Selecione uma célula primeiro.'); onPatch({ cellStyles: { ...styles, [key]: { ...currentStyle, ...patch } } }); }; const setCell = (ri, ci, value) => onPatch({ rows: rows.map((r, rix) => rix === ri ? r.map((c, cix) => cix === ci ? value : c) : r) }); const deleteRow = ri => { if (rows.length <= 1) return; const oldRows = deepClone(rows), oldStyles = deepClone(styles); const next = rows.filter((_, i) => i !== ri); const remapped = {}; Object.entries(styles).forEach(([k,v]) => { const [r,c] = k.split(':').map(Number); if (r === ri) return; remapped[`${r > ri ? r - 1 : r}:${c}`] = v; }); onPatch({ rows: next, cellStyles: remapped, selectedCell: null }); pushUndo('Linha apagada.', () => onPatch({ rows: oldRows, cellStyles: oldStyles, selectedCell: null })); }; return <div className="dm-table-widget"><div className="dm-table-toolbar"><Button onClick={() => onPatch({ struct: !widget.struct })}>{widget.struct ? '🔓' : '🔒'} Estrutura</Button><Button onClick={() => { const start = rows.length > 1 ? 1 : 0; const hit = start + Math.floor(Math.random() * Math.max(1, rows.length - start)); onPatch({ rollHit: hit }); notify(`Resultado: ${rows[hit]?.join(' — ') || ''}`); }}>🎲 Linha aleatória</Button></div><div className="dm-table-format"><Button onClick={() => patchStyle({ fontSize: Math.max(8,currentStyle.fontSize-1) })}>A−</Button><span>{currentStyle.fontSize}px</span><Button onClick={() => patchStyle({ fontSize: Math.min(36,currentStyle.fontSize+1) })}>A+</Button><Button className={currentStyle.bold?'is-active':''} onClick={() => patchStyle({ bold:!currentStyle.bold })}><b>B</b></Button><Button className={currentStyle.italic?'is-active':''} onClick={() => patchStyle({ italic:!currentStyle.italic })}><i>I</i></Button><Button className={currentStyle.underline?'is-active':''} onClick={() => patchStyle({ underline:!currentStyle.underline })}><u>U</u></Button><input type="color" value={currentStyle.color} onInput={e => patchStyle({ color:e.currentTarget.value })}/><Button onClick={() => { if (!selected) return notify('Selecione uma célula primeiro.'); const next = {...styles}; delete next[key]; onPatch({ cellStyles: next }); }}>Tx</Button><small>{selected?'Célula selecionada':'Selecione uma célula'}</small></div>{widget.struct && <div className="dm-inline"><Button onClick={() => onPatch({ rows:[...rows,Array(rows[0]?.length||2).fill('')] })}>＋ Linha</Button><Button onClick={() => onPatch({ rows:rows.map(r => [...r,'']) })}>＋ Coluna</Button></div>}<div className="dm-table-wrap"><table><tbody>{rows.map((row,ri) => <tr key={ri} className={widget.rollHit===ri?'is-hit':''}>{row.map((cell,ci) => { const st={fontSize:10,color:'#e7e5e4',bold:false,italic:false,underline:false,...(styles[`${ri}:${ci}`]||{})}; const sel=selected?.ri===ri&&selected?.ci===ci; return <td key={ci} className={sel?'is-selected':''} onClick={() => onPatch({ selectedCell:{ri,ci} })}><input value={cell} onFocus={() => onPatch({ selectedCell:{ri,ci} })} onChange={e => setCell(ri,ci,e.target.value)} style={{fontSize:st.fontSize,color:st.color,fontWeight:st.bold?700:400,fontStyle:st.italic?'italic':'normal',textDecoration:st.underline?'underline':'none'}}/></td>; })}{widget.struct && <td className="dm-table-delete"><button onClick={() => deleteRow(ri)}>×</button></td>}</tr>)}</tbody></table></div></div>; }

function NpcWidget({ widget, onPatch, addCombatant }) { const n=widget.npc||{}; const set=patch=>onPatch({npc:{...n,...patch}}); return <div className="dm-npc"><input className="wide" value={n.name||''} onChange={e=>set({name:e.target.value})} placeholder="Nome do NPC"/><div className="dm-grid-3"><input value={n.hp??''} onChange={e=>set({hp:e.target.value})} placeholder="PV atual"/><input value={n.hpMax??''} onChange={e=>set({hpMax:e.target.value})} placeholder="PV máx"/><input value={n.def??''} onChange={e=>set({def:e.target.value})} placeholder="CA/DEF"/></div><div className="dm-grid-2"><input value={n.init??''} onChange={e=>set({init:e.target.value})} placeholder="Iniciativa"/><input value={n.cond??''} onChange={e=>set({cond:e.target.value})} placeholder="Condição"/></div><input value={n.attack??''} onChange={e=>set({attack:e.target.value})} placeholder="Ataque / teste"/><input value={n.damage??''} onChange={e=>set({damage:e.target.value})} placeholder="Dano"/><textarea rows="4" value={n.notes||''} onChange={e=>set({notes:e.target.value})} placeholder="Notas rápidas"/><div className="dm-inline"><Button onClick={() => addCombatant({name:n.name||'NPC',init:n.init||'',hp:`${n.hp??''}${n.hpMax?`/${n.hpMax}`:''}`,cond:n.cond||''})}>⚔ Adicionar à Iniciativa</Button><Button onClick={() => set({hp:n.hpMax})}>PV Máx</Button></div></div>; }
function ClockWidget({ widget, onPatch }) { const c=widget.clock||{name:'Relógio',value:0,max:6}; const set=patch=>onPatch({clock:{...c,...patch}}); return <div className="dm-clock"><input className="dm-clock__name" value={c.name} onChange={e=>set({name:e.target.value})}/><div className="dm-clock__segments">{Array.from({length:c.max},(_,i)=><button key={i} className={i<c.value?'is-on':''} onClick={()=>set({value:i+1})}/>)}</div><strong>{c.value}/{c.max}</strong><div className="dm-inline"><Button onClick={()=>set({value:Math.max(0,c.value-1)})}>−</Button><select value={c.max} onChange={e=>set({max:Number(e.target.value),value:Math.min(c.value,Number(e.target.value))})}>{[4,6,8,10,12].map(x=><option key={x}>{x}</option>)}</select><Button onClick={()=>set({value:Math.min(c.max,c.value+1)})}>＋</Button><Button onClick={()=>set({value:0})}>↺</Button></div></div>; }

function sanitizeLegacyHtml(html) { if (!html || typeof window === 'undefined' || typeof DOMParser === 'undefined') return ''; const doc=new DOMParser().parseFromString(String(html),'text/html'); doc.querySelectorAll('script,style,iframe,object,embed,link,meta').forEach(node=>node.remove()); doc.querySelectorAll('*').forEach(node=>[...node.attributes].forEach(attr=>{ const name=attr.name.toLowerCase(); const val=String(attr.value||'').trim().toLowerCase(); if(name.startsWith('on')||(['href','src','xlink:href'].includes(name)&&val.startsWith('javascript:'))) node.removeAttribute(attr.name); })); return doc.body.innerHTML; }
function ReferenceWidget({ widget }) { return <div className="dm-reference"><div className="dm-reference__intro"><strong>{widget.subtitle||'Referência rápida'}</strong><span>{widget.sections?.length||0} seções</span></div>{(widget.sections||[]).map((s,i)=><details key={i} open={i===0}><summary>{s.title}</summary><div>{s.body&&<ul>{s.body.map((x,idx)=><li key={idx}>{x}</li>)}</ul>}{s.rows&&<table><tbody>{s.rows.map((r,idx)=><tr key={idx}>{r.map((c,ci)=><td key={ci}>{c}</td>)}</tr>)}</tbody></table>}{s.html&&<div className="dm-legacy-reference" dangerouslySetInnerHTML={{__html:sanitizeLegacyHtml(s.html)}}/>}</div></details>)}</div>; }
function PJWidget({ widget, addCombatant }) { const q=widget.quick||buildPJQuick(widget.pjData||{}); return <div className="dm-pj-widget"><div className="dm-pj-widget__hero"><div>👤</div><section><h3>{q.name}</h3><p>{q.subtitle}</p><small>{systemLabel(q.system)}</small></section></div><div className="dm-pj-stats">{(q.stats||[]).map(s=><div key={s.label}><strong>{s.value}</strong><span>{s.label}</span></div>)}</div><Button onClick={()=>addCombatant({name:q.name,init:q.initiative||'',hp:q.hp||'',cond:''})}>⚔ Adicionar à Iniciativa</Button><div className="dm-pj-sections">{(q.sections||[]).map((section,i)=><details key={i}><summary>{section.title}</summary><ul>{section.items.map((item,idx)=><li key={idx}>{item}</li>)}</ul></details>)}</div></div>; }

export default function DMLiteApp() {
  const [shields,setShields]=useState(()=>loadShields()); const [currentId,setCurrentId]=useState(()=>loadCurrentShieldId()); const [createOpen,setCreateOpen]=useState(false); const [importOpen,setImportOpen]=useState(false); const [editingId,setEditingId]=useState(null); const [exportingId,setExportingId]=useState(null); const [updatesOpen,setUpdatesOpen]=useState(false); const [aboutOpen,setAboutOpen]=useState(false); const [toast,setToast]=useState(null); const toastTimer=useRef(null); const saveTimer=useRef(null);
  const current=shields.find(s=>s.id===currentId)||null; const notify=useCallback((message,undo)=>{clearTimeout(toastTimer.current);setToast({message,undo});toastTimer.current=setTimeout(()=>setToast(null),undo?6500:2600);},[]); const pushUndo=useCallback((message,action)=>notify(message,action),[notify]);
  useEffect(()=>{saveCurrentShieldId(currentId);},[currentId]); useEffect(()=>{clearTimeout(saveTimer.current);saveTimer.current=setTimeout(()=>{const result=saveShields(shields);if(!result.ok)notify('Não foi possível salvar. O armazenamento local pode estar cheio.');},180);return()=>clearTimeout(saveTimer.current);},[shields,notify]);
  const updateCurrent=useCallback(next=>setShields(list=>list.map(s=>s.id===currentId?migrateShield(typeof next==='function'?next(s):next):s)),[currentId]); const openShield=id=>{setCurrentId(id);window.history.replaceState(null,'','/dm/');}; const backHome=()=>{setCurrentId('');document.title='DM Lite';}; const createShield=(kind,name,genre)=>{const sh=presetShield(kind,name,genre);setShields(list=>[...list,sh]);setCreateOpen(false);setCurrentId(sh.id);notify('Escudo criado.');}; const duplicateShield=id=>{const src=shields.find(s=>s.id===id);if(!src)return;const copy=migrateShield({...deepClone(src),id:uid('shield'),name:`${src.name} (Cópia)`,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),widgets:src.widgets.map(w=>({...deepClone(w),id:uid('widget')}))});setShields(list=>[...list,copy]);notify('Escudo duplicado.');}; const deleteShield=id=>{const idx=shields.findIndex(s=>s.id===id);if(idx<0)return;const gone=deepClone(shields[idx]);const next=shields.filter(s=>s.id!==id);setShields(next);if(currentId===id)setCurrentId('');pushUndo('Escudo apagado.',()=>setShields(list=>{const restored=[...list];restored.splice(Math.min(idx,restored.length),0,gone);return restored;}));}; const editShield=shields.find(s=>s.id===editingId)||null; const exportShield=shields.find(s=>s.id===exportingId)||null; const doImportPayload=(payload,forcedError)=>{if(forcedError)return notify(forcedError);try{const sh=importShieldPayload(payload,shields);setShields(list=>[...list,sh]);setImportOpen(false);notify(`Escudo “${sh.name}” importado.`);}catch(e){notify(e.message||'Arquivo inválido.');}}; const doImportCode=code=>{try{doImportPayload(decodeShieldCode(code));}catch(e){notify(e.message||'Código inválido.');}};
  useEffect(()=>{document.title=current?`${current.name} — DM Lite`:'DM Lite';},[current?.name]);
  return <>{current?<ShieldEditor shield={current} onChange={updateCurrent} onBack={backHome} notify={notify} pushUndo={pushUndo}/>:<Home shields={shields} onOpen={openShield} onCreate={()=>setCreateOpen(true)} onImport={()=>setImportOpen(true)} onEdit={setEditingId} onDuplicate={duplicateShield} onDelete={deleteShield} onExport={setExportingId} onOpenUpdates={()=>setUpdatesOpen(true)} onOpenAbout={()=>setAboutOpen(true)}/>}<CreateShieldModal open={createOpen} onClose={()=>setCreateOpen(false)} onCreate={createShield}/><EditShieldModal shield={editShield} onClose={()=>setEditingId(null)} onSave={(name,genre)=>{setShields(list=>list.map(s=>s.id===editingId?{...s,name,genre,updatedAt:new Date().toISOString()}:s));setEditingId(null);notify('Dados do escudo atualizados.');}}/><ImportShieldModal open={importOpen} onClose={()=>setImportOpen(false)} onImportPayload={doImportPayload} onImportCode={doImportCode}/><ExportShieldModal shield={exportShield} onClose={()=>setExportingId(null)} notify={notify}/><UpdatesModal open={updatesOpen} onClose={()=>setUpdatesOpen(false)}/><AboutModal open={aboutOpen} onClose={()=>setAboutOpen(false)}/><Toast toast={toast} onUndo={()=>toast?.undo?.()} onDismiss={()=>setToast(null)}/></>;
}
